'use server';

import { ai } from '@/ai/genkit';
import {
  type NextStepInput,
  NextStepInputSchema,
  type NextStepOutput,
  NextStepOutputSchema,
} from '@/ai/schemas/next-step';

export async function getNextStep(
  input: NextStepInput
): Promise<NextStepOutput> {
  return getNextStepFlow(input);
}

const getNextStepFlow = ai.defineFlow(
  {
    name: 'getNextStepFlow',
    inputSchema: NextStepInputSchema,
    outputSchema: NextStepOutputSchema,
  },
  async (input) => {
    const historyLog =
      input.history.length > 0
        ? `${input.history
            .map((m) => `- ${m.role}: ${m.content}`)
            .join('\n')}`
        : 'empty';

    const fullPrompt = `You are a friendly AI assistant for RenoAI, a commercial real estate renovation budgeting tool. Your goal is to guide the user to provide the following information by asking one question at a time:
- squareFootage (number)
- planType ('Open Plan' or 'Mixed Use')
- privateOffices (number)
- ceilingType ('Standard' or 'Open')
- ceilingHeight (number)

You will be given the conversation history and a JSON object of the data collected so far. Based on this, your task is to process the user's latest message and generate the next step by following these rules:
1.  **Analyze the user's last message:** Look for any of the required data points.
2.  **Update collected data:** In the \`updatedData\` field, return a JSON object containing ALL data collected so far, including any new information from the user's last message. If the user provided a value, add it. If they didn't, keep the existing data.
3.  **Determine next question:** Figure out the next piece of information needed.
4.  **Formulate response:**
    *   If more information is needed, your \`response\` must be a single, simple question to get it.
    *   If the user gives an invalid value (like 'Red' for 'planType'), your \`response\` should be a question that clarifies the valid options.
    *   If all information is collected, set \`isComplete\` to \`true\` and set your \`response\` to a confirmation message like "Thanks! I have everything I need to generate your estimate."

**CRITICAL:** You MUST respond with a valid JSON object that conforms to the output schema. Do not include any other text or formatting.

Conversation History:
${historyLog}

Data Collected So Far:
${JSON.stringify(input.collectedData, null, 2)}
`;

    const { output } = await ai.generate({
      prompt: fullPrompt,
      output: { schema: NextStepOutputSchema },
      model: 'googleai/gemini-2.5-flash',
      config: {
        temperature: 0.2,
      },
    });

    if (!output) {
      throw new Error('AI failed to generate a response.');
    }
    return output;
  }
);
